BEGIN READ ONLY;SET LOCAL statement_timeout='20s';SELECT jsonb_build_object('readOnly',current_setting('transaction_read_only'),'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('identity',p.oid::regprocedure::text,'md5',md5(replace(pg_get_functiondef(p.oid),chr(13),'')),'definition',pg_get_functiondef(p.oid))),'[]') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind='f' AND n.nspname IN('public','backend_core','proforma_backend') AND p.prosrc ~ '(^|[^A-Za-z0-9_])tax([^A-Za-z0-9_]|$)'));COMMIT;